text:
{
  "filename": "style.css",
  "content": "@import url('https://fonts.googleapis.com/css2?family=Open+Sans:wght@400;700&display=swap');

* {
  box-sizing: border-box;
}

body {
  font-family: 'Open Sans', sans-serif;
  margin: 0;
  padding: 0;
  font-size: 16px;
  color: #333;
  background-color: #f4f4f4;
}

header {
  background-color: #4CAF50;
  color: white;
  padding: 10px;
  text-align: center;
}

nav {
  display: flex;
  justify-content: center;
}

nav ul {
  list-style-type: none;
  padding: 0;
}

nav ul li {
  margin: 0 10px;
}

nav ul li a {
  color: white;
  text-decoration: none;
}

nav ul li a:hover {
  text-decoration: underline;
}

.container {
  max-width: 800px;
  margin: 0 auto;
  padding: 20px;
}

.hero-section {
  background-color: #4CAF50;
  padding: 20px;
  color: white;
}

.hero-section h1 {
  font-size: 3em;
}

.hero-section p {
  font-size: 1.2em;
}

.menu-items {
  padding: 20px;
}

.menu-list {
  list-style-type: none;
  padding: 0;
}

.menu-list li {
  margin-bottom: 10px;
}

.menu-list a {
  color: #333;
  text-decoration: none;
}

.menu-list a:hover {
  text-decoration: underline;
}

.contact-info {
  padding: 20px;
}

.contact-info h2 {
  font-size: 1.5em;
}

.contact-info p {
  font-size: 1.2em;
}

footer {
  background-color: #4CAF50;
  color: white;
  padding: 10px;
  text-align: center;
}

@media (max-width: 768px) {
  .nav-links {
    flex-direction: column;
  }
}

@media (min-width: 1200px) {
  .nav-links {
    flex-direction: row;
  }
}"
}
